<div class="message-input">
    <textarea @bind="text" @bind:event="oninput" placeholder="@Placeholder"
              @onkeydown="HandleKeyDown" rows="1"></textarea>
    <button @onclick="Send" disabled="@string.IsNullOrWhiteSpace(text)">@ButtonText</button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message...";
    [Parameter] public string ButtonText { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSend { get; set; }

    private string text = "";

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await Send();
        }
    }

    private async Task Send()
    {
        var trimmed = text.Trim();
        if (string.IsNullOrEmpty(trimmed)) return;
        text = "";
        await OnSend.InvokeAsync(trimmed);
    }
}
"}

