@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>
<HeadContent>
    <link rel="stylesheet" href="css/chat.css" />
</HeadContent>

<div class="chat-layout @(isThreadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    SelectedChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea @ref="messageAreaRef"
                 ChannelName="@(selectedChannel?.Name ?? "")"
                 ChannelDescription="@(selectedChannel?.Description ?? "")"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoadingMore="isLoadingMore"
                 OnLoadMore="LoadMoreMessages"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage" />

    @if (isThreadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private Channel? selectedChannel;
    private int selectedChannelId;
    private int messageSkip;
    private const int PageSize = 50;
    private bool isLoadingMore;
    private bool hasMoreMessages = true;

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];
    private int? activeThreadRootId;

    private MessageArea? messageAreaRef;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messageSkip = 0;
        hasMoreMessages = true;
        threadSummaries.Clear();

        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messageSkip = messages.Count;

        if (messages.Count < PageSize)
            hasMoreMessages = false;

        await ChatService.MarkChannelReadAsync(channelId);
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
            channels[idx] = channels[idx] with { UnreadCount = 0 };

        CloseThreadInternal();
        await LoadThreadSummaries();
    }

    private async Task LoadThreadSummaries()
    {
        foreach (var msg in messages.Where(m => m.ReplyToId is null))
        {
            try
            {
                var replies = await ChatService.GetThreadAsync(msg.Id);
                if (replies.Count > 0)
                {
                    threadSummaries[msg.Id] = new ThreadSummary(
                        msg.Id, replies.Count, replies.Max(r => r.SentAt));
                }
            }
            catch
            {
                // No thread exists for this message
            }
        }
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || !hasMoreMessages) return;
        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messageSkip, PageSize);
        if (older.Count < PageSize)
            hasMoreMessages = false;

        messages.InsertRange(0, older);
        messageSkip += older.Count;
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(msg);

        if (messageAreaRef is not null)
            await messageAreaRef.ScrollToBottomAsync();
    }

    private async Task OpenThread(int rootMessageId)
    {
        activeThreadRootId = rootMessageId;
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        isThreadOpen = true;

        if (threadReplies.Count > 0)
        {
            threadSummaries[rootMessageId] = new ThreadSummary(
                rootMessageId, threadReplies.Count, threadReplies.Max(r => r.SentAt));
        }
    }

    private void CloseThreadInternal()
    {
        isThreadOpen = false;
        activeThreadRootId = null;
        threadRootMessage = null;
        threadReplies = [];
    }

    private void CloseThread() => CloseThreadInternal();

    private async Task SendThreadReply(string content)
    {
        if (activeThreadRootId is null) return;

        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, activeThreadRootId);
        threadReplies.Add(reply);

        threadSummaries[activeThreadRootId.Value] = new ThreadSummary(
            activeThreadRootId.Value, threadReplies.Count, reply.SentAt);
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        var msg = messages.FirstOrDefault(m => m.Id == reaction.MessageId);
        if (msg is null) return;

        var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
        if (existing is not null)
        {
            if (!existing.Users.Contains("You"))
                existing.Users.Add("You");
        }
        else
        {
            msg.Reactions.Add(new Reaction(reaction.Emoji, ["You"]));
        }
    }
}

