arguments.file_text:
/* ===== Chat Layout ===== */
.chat-layout {
    display: flex;
    height: calc(100vh - 3.5rem);
    overflow: hidden;
    margin: -1rem -1.5rem;
    background: #36393f;
}

/* ===== Channel Sidebar ===== */
.channel-sidebar {
    width: 240px;
    min-width: 200px;
    background: #2b2d31;
    color: #949ba4;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1e1f22;
    flex-shrink: 0;
}

.channel-sidebar h3 {
    padding: 16px 16px 8px;
    margin: 0;
    font-size: 12px;
    text-transform: uppercase;
    color: #949ba4;
    letter-spacing: 0.02em;
    font-weight: 700;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
    padding: 0 8px;
}

.channel-item {
    display: flex;
    align-items: center;
    padding: 7px 10px;
    cursor: pointer;
    border-radius: 4px;
    margin-bottom: 2px;
    gap: 8px;
    transition: background-color 0.1s;
}

.channel-item:hover {
    background: #35373c;
    color: #dbdee1;
}

.channel-item.active {
    background: #404249;
    color: #f2f3f5;
}

.channel-info {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.channel-name {
    font-weight: 500;
    font-size: 15px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    line-height: 1.3;
}

.channel-desc {
    font-size: 11px;
    color: #80848e;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    line-height: 1.3;
}

.unread-badge {
    background: #f23f43;
    color: white;
    font-size: 11px;
    font-weight: 700;
    padding: 1px 6px;
    border-radius: 8px;
    min-width: 18px;
    text-align: center;
    flex-shrink: 0;
    line-height: 16px;
}

/* ===== Message Area ===== */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: #313338;
    color: #dbdee1;
}

.channel-header {
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

.channel-header h2 {
    margin: 0;
    font-size: 16px;
    color: #f2f3f5;
    font-weight: 600;
    line-height: 1.3;
}

.channel-header p {
    margin: 2px 0 0;
    font-size: 12px;
    color: #949ba4;
    line-height: 1.3;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 0;
}

/* ===== Message Bubble ===== */
.message-bubble {
    position: relative;
    padding: 2px 48px 2px 72px;
    min-height: 2.75rem;
}

.message-bubble:hover {
    background: #2e3035;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.message-header .author {
    font-weight: 600;
    color: #f2f3f5;
    font-size: 15px;
    cursor: pointer;
}

.message-header .author:hover {
    text-decoration: underline;
}

.message-header .timestamp {
    font-size: 12px;
    color: #949ba4;
}

.message-content {
    font-size: 15px;
    line-height: 1.375;
    word-break: break-word;
    white-space: pre-wrap;
}

.reactions {
    display: flex;
    gap: 4px;
    margin-top: 4px;
    flex-wrap: wrap;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    background: #2b2d31;
    border: 1px solid transparent;
    border-radius: 8px;
    padding: 2px 8px;
    font-size: 14px;
    color: #dbdee1;
    cursor: pointer;
    transition: background-color 0.1s, border-color 0.1s;
    line-height: 1.4;
}

.reaction-badge:hover {
    background: #36383d;
    border-color: #5865f2;
}

.thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 13px;
    cursor: pointer;
    padding: 4px 0 2px;
    font-weight: 500;
    display: block;
}

.thread-link:hover {
    text-decoration: underline;
}

/* ===== Message Hover Actions ===== */
.message-actions {
    position: absolute;
    top: -16px;
    right: 14px;
    display: flex;
    gap: 0;
    background: #2b2d31;
    border: 1px solid #1e1f22;
    border-radius: 4px;
    overflow: hidden;
    box-shadow: 0 2px 8px rgba(0,0,0,0.24);
    z-index: 1;
}

.message-actions button {
    background: none;
    border: none;
    padding: 6px 8px;
    cursor: pointer;
    border-radius: 0;
    font-size: 18px;
    line-height: 1;
    color: #b5bac1;
}

.message-actions button:hover {
    background: #36383d;
    color: #dbdee1;
}

.emoji-picker {
    position: absolute;
    top: -16px;
    right: 100px;
    display: flex;
    gap: 2px;
